select jsonb_build_object('release_id',r.release_id,'input_sha256',s.content_sha256,'engine_sha256',r.engine_sha256,'exported_on',current_date,'source_provenance',(select jsonb_agg(x - 'observations') from jsonb_array_elements(s.payload->'inputs') x),'history',(select jsonb_agg(jsonb_build_object('model',hp.model_key,'year',hp.year,'actual',hp.actual) order by hp.model_key,hp.year) from research.impact_visual_point hp where hp.release_id=r.release_id and hp.baseline_year=1975 and hp.group_key='FI' and hp.factor_key in ('productivity','prices') and hp.value_status='computed'),'runs',(select jsonb_agg(jsonb_build_object('model',q.model_key,'baseline',q.baseline_year,'unit',q.actual_unit,'points',q.points)) from (select p.model_key,p.baseline_year,max(p.actual_unit) actual_unit,jsonb_agg(jsonb_build_object('year',p.year,'factor',p.factor_key,'actual',p.actual,'effect',p.effect,'status',p.value_status) order by p.year,p.factor_key) points from research.impact_visual_point p where p.release_id=r.release_id and p.group_key='FI' and ((p.model_key='age_structure' and p.baseline_year=1987) or (p.model_key in ('production_components','real_income_components') and p.baseline_year=1990)) group by p.model_key,p.baseline_year) q)) export from research.impact_release r join research.impact_snapshot s using(snapshot_id) join research.impact_release_status st using(release_id) where st.status='computed' order by r.created_at desc limit 1;
